describe("applyConfigPatch 错误路径（#110）", () => {
  let na;
  let invalid;
  let broken;
  let logWarnHit;

  beforeAll(async () => {
    // settings 服务不可用
    na = await applyConfigPatch(basePatchDeps({ writable: () => false }), { patch: {} });
    // 非法 settings
