// ===== 变异加固块（round=3 CI 回归：迁移重放/路由面/校验分支断言进 tap 面） =====
// 背景：smoke.test.ts 不在 stryker tap testFiles 内，其覆盖的行为在变异判定中全部
// 存活/noCov。本块把关键行为断言移植到 unit-apply（tap 面内），杀灭新代码
// （resumeMigrateFromBak / migrateFileConfig / applyConfigPatch / buildConfigRoutes /
// installLanProxySettings / warnLog）的存活 mutant。
describe("变异加固块（round=3 CI 回归：迁移重放/路由面/校验分支断言进 tap 面）", () => {
  // 本块所有 apply 调用统一 DSH_HOME 隔离 + disposer 回收（防转发器 server /
  // scheduleSync timer 句柄泄漏挂起事件循环，也防迁移触达真实 ~/.dsh/lan-proxy）。
  const prevHome = process.env.DSH_HOME;
  let blockHome;
  const cleanupFns = [];

  /** 构造最小 fake ctx：收集 lifecycle disposer；enabled 可关避免真实 listen。 */
  const makeCtx = (over = {}) => {
    const disposers = [];
    const routes = [];
    const ctx = {
      logger:
        over.logger !== undefined
          ? over.logger
          : { info: () => {}, warn: () => {}, error: () => {} },
      webServer: makeFakeWebServer({ register: (route) => routes.push(route) }),
      inject() {},
      effect(fn) {
        const d = fn();
        if (typeof d === "function") disposers.push(d);
        return d;
      },
      ...over,
      get _routes() {
        return routes;
      },
      [Symbol.for("dispose")]() {
        for (const d of [...disposers].reverse()) {
          try {
            d();
          } catch {}
        }
      },
    };
    cleanupFns.push(ctx[Symbol.for("dispose")]);
    return ctx;
  };

  beforeAll(() => {
    blockHome = mkdtempSync(join(tmpdir(), "dsh-lan-proxy-mut-block-"));
    process.env.DSH_HOME = blockHome;
  });

  afterAll(() => {
    for (const fn of [...cleanupFns].reverse()) {
      try {
        fn();
      } catch {}
    }
    process.env.DSH_HOME = prevHome;
    rmSync(blockHome, { recursive: true, force: true });
  });

  // 非法 logger 仅属于 warnLog 的降级契约，不得进入真实转发器的异步回调。
  describe("A. warnLog 与 settings 降级", () => {
    it.each([
      { title: "无 logger", ctx: {} },
      { title: "warn 非函数", ctx: { logger: { warn: "not-a-function" } } },
    ])("$title 不抛异常", ({ ctx }) => {
      expect(() => warnLog(ctx, "settings unavailable")).not.toThrow();
    });

    it("有效 logger 收到原消息并保留方法接收者", () => {
      const logger = {
        messages: [],
        warn(message) {
          this.messages.push(message);
        },
      };
      warnLog({ logger }, "settings unavailable");
      expect(logger.messages).toEqual(["settings unavailable"]);
    });

    it("settings 缺少 register 时告警且仍注册 health 路由", () => {
      const messages = [];
      const ctx = makeCtx({
        logger: {
          info() {},
          error() {},
          warn(message) {
            messages.push(message);
          },
        },
        inject(services, callback) {
          if (services.includes("settings")) callback({ settings: {} });
        },
      });
      try {
        apply(ctx, { enabled: false, httpsEnabled: false, host: "127.0.0.1", port: 0 });
        expect(messages).toEqual([
          "dsh-lan-proxy: settings 服务缺少 register 能力 — 设置命名空间未注册，卡片降级",
        ]);
        expect(ctx._routes.filter((r) => r.path === ROUTES.health).length).toBe(1);
      } finally {
        ctx[Symbol.for("dispose")]();
      }
    });
  });

  // ---- B. installLanProxySettings 全分支（inject 缺失/服务缺 register/register 抛错/detach 回落/watch 触发/isUnloading 门控）----
  describe("B. installLanProxySettings 全分支", () => {
    // B1: ctx.inject 缺失 → 降级不抛（原脚本此分支无断言，保留其执行）。
    beforeAll(() => {
      apply(makeCtx({ port: 3081 }), { enabled: false, host: "127.0.0.1", httpsEnabled: false });
    }, 30000);

    // B2: settings 服务存在但无 register → 降级；register 抛错 → 降级。
    describe("B2: settings 服务异常态", () => {
      const services = [
        { label: "missing", service: undefined },
        { label: "no-register", service: {} },
        {
          label: "throws",
          service: {
            register() {
              throw new Error("dup");
            },
          },
        },
      ];
      const results = [];

      beforeAll(() => {
        for (const { service } of services) {
          const ctx = makeCtx({
            inject(services2, fn) {
              if (services2.includes("settings"))
                fn({
                  settings: service,
                  effect(fn2) {
                    return fn2();
                  },
                });
            },
          });
          apply(ctx, { host: "127.0.0.1", port: 0, httpsEnabled: false, enabled: true });
          results.push(ctx._routes.length >= 2);
        }
      }, 30000);

      const titled = services.map((s, i) => ({
        title: `service 异常态（${s.label}#${i}）不阻断 health/config 注册`,
        i,
      }));
      it.each(titled)("$title", ({ i }) => {
        expect(results[i]).toBe(true);
      });
    });

    // B3: attach → watch 挂接 → 非 unloading 态触发 cb 不抛；unloading 态执行 disposers 门控跳过。
    describe("B3: attach → watch 挂接 → isUnloading 门控", () => {
      const makeScope = () => {
        const st = { watchCbs: [], disposed: false };
        return {
          st,
          scope: {
            get() {
              return { port: 4321 };
            },
            watch(cb) {
              st.watchCbs.push(cb);
              return () => {
                st.disposed = true;
              };
            },
            async update() {},
            async replace() {},
          },
        };
      };
      let nsSeen;
      let watchCbsLen;
      let gateCompleted;

      beforeAll(() => {
        const s = makeScope();
        const fiberStates = [];
        const ctx = makeCtx({
          get fiber() {
            return { state: fiberStates[fiberStates.length - 1] };
          },
          inject(services, fn) {
            if (services.includes("settings")) {
              fn({
                settings: {
                  register(ns) {
                    nsSeen = ns;
                    return s.scope;
                  },
                },
                effect(fn2) {
                  const d = fn2();
                  return d;
                },
              });
            }
          },
        });
        apply(ctx, { host: "127.0.0.1", port: 0, httpsEnabled: false, printBanner: false });
        watchCbsLen = s.st.watchCbs.length;
        fiberStates.push("attached");
        s.st.watchCbs[0]();
        fiberStates.push("unloading");
        ctx[Symbol.for("dispose")]();
        fiberStates.pop();
        gateCompleted = true;
      }, 30000);

      it("命名空间名", () => {
        expect(nsSeen).toBe(SETTINGS_NS);
      });

      it("scope.watch 已挂接", () => {
        expect(watchCbsLen >= 1).toBe(true);
      });

      it("isUnloading 门控路径执行不抛错", () => {
        expect(gateCompleted).toBeTruthy();
      });
    });
  });

  // ---- C. migrateFileConfig 全分支 outcome 精确断言（含中断重放四分支）----
  describe("C. migrateFileConfig 全分支 outcome 精确断言", () => {
    const okScope = () => ({
      updates: [],
      async update(p) {
        this.updates.push(p);
        return Promise.resolve();
      },
    });

    // C1: 双文件都不存在 → idle 六字段全 false。
    describe("C1: 双文件都不存在 → idle", () => {
      let idleOut;

      beforeAll(async () => {
        const idleDir = mkdtempSync(join(tmpdir(), "dsh-lan-proxy-mut-idle-"));
        idleOut = await migrateFileConfig(idleDir, okScope());
        rmSync(idleDir, { recursive: true, force: true });
      });

      it("idle outcome 全 false", () => {
        expect(idleOut).toEqual({
          performed: false,
          migrated: false,
          rolledBack: false,
          skippedCorrupt: false,
          resumed: false,
        });
      });
    });

    // C2: 成功迁移 → performed+migrated，其余 false；损坏 JSON catch 分支；
    //     非对象 JSON；sanitize null；空对象 sanitized（keys=0 → skippedCorrupt）。
    describe("C2: 迁移 outcome 分支矩阵", () => {
      const cases = [
        {
          name: "success",
          raw: JSON.stringify({ port: 4082 }),
          expected: {
            performed: true,
            migrated: true,
            rolledBack: false,
            skippedCorrupt: false,
            resumed: false,
          },
        },
        {
          name: "broken-json",
          raw: "{oops",
          expected: {
            performed: true,
            migrated: false,
            rolledBack: false,
            skippedCorrupt: true,
            resumed: false,
          },
        },
        {
          name: "non-object",
          raw: JSON.stringify([1]),
          expected: {
            performed: true,
            migrated: false,
            rolledBack: false,
            skippedCorrupt: true,
            resumed: false,
          },
        },
        {
          name: "invalid-value",
          raw: JSON.stringify({ port: "x" }),
          expected: {
            performed: true,
            migrated: false,
            rolledBack: false,
            skippedCorrupt: true,
            resumed: false,
          },
        },
        {
          name: "empty-object",
          raw: JSON.stringify({}),
          expected: {
            performed: true,
            migrated: false,
            rolledBack: false,
            skippedCorrupt: true,
            resumed: false,
          },
        },
      ];
      const records = [];

      beforeAll(async () => {
        for (const { name, raw } of cases) {
          const dir = mkdtempSync(join(tmpdir(), `dsh-lan-proxy-mut-${name}-`));
          writeFileSync(join(dir, "config.json"), raw);
          const scope = okScope();
          const out = await migrateFileConfig(dir, scope);
          // bak 标记必须在 rmSync 之前观测（目录随即被回收）
          records.push({
            out,
            bakExists: existsSync(join(dir, MIGRATED_BAK_NAME)),
            updates: scope.updates,
          });
          rmSync(dir, { recursive: true, force: true });
        }
      });

      const titledOutcome = cases.map((c, i) => ({ title: `case=${c.name} outcome`, i }));
      it.each(titledOutcome)("$title", ({ i }) => {
