      if (!init?.method && String(input).endsWith("/config")) throw new Error("boom-load");
      return servingFetch(input, init);
    };
    const view = render(card());
    await act(async () => {});
    expect(view.getByText("settingsLoading")).toBeTruthy();
  });
});

